    'troubleshooting' => [
        ['q' => 'Phones and tablets can\'t connect', 'a' => 'Check that the device is on the same network as the StageWatch PC, that Allow other devices is ticked in Settings → Remote, and that StageWatch is allowed through the Windows firewall on private networks. Then type the exact address shown in Settings → Remote.'],
        ['q' => 'A screen says NOT CONNECTED', 'a' => 'That screen hasn\'t heard from StageWatch for about 6 seconds, usually because of the Wi-Fi, a sleeping device or the PC itself. It reconnects by itself. Until it does, trust the operator\'s screen.'],
        ['q' => 'No NDI source appears', 'a' => 'Install the free NDI Runtime (NDI Tools) on the StageWatch PC, then press NDI again.'],
        ['q' => 'Companion shows disconnected', 'a' => 'In StageWatch, turn on Settings → Companion → Enabled. If Companion runs on another computer, tick Bind all interfaces and allow StageWatch through the firewall. Companion control needs Pro, Production or the trial, and Companion 5.0 or newer.'],
        ['q' => 'Some Companion keys are grey', 'a' => 'Grey keys are features your licence doesn\'t include. They work as soon as a licence that covers them is installed.'],
