        ['q' => 'LTC timecode isn\'t being read', 'a' => 'Feed the timecode into an audio line input, ideally a USB audio interface, rather than a microphone input with enhancements. Then choose that input in Settings → Integrations → Time.'],
        ['q' => 'StageWatch closed in the middle of a show', 'a' => 'It restarts itself and puts the show back where it was. After a power cut, it offers the show back the next time it starts.'],
        ['q' => 'How do I install my licence file?', 'a' => 'Download the file from Licences in your client portal. In StageWatch, open Help → License → Install license file, choose the file and restart StageWatch.'],
        ['q' => 'I have a new PC or reinstalled Windows', 'a' => 'Copy the new hardware ID from Help → License → Plans or Settings → About, and send it through your client portal. A fresh licence file is issued for the new PC. Changing networks, docks or Wi-Fi never affects a licence.'],
        ['q' => 'Support asked for diagnostics', 'a' => 'Use Settings → About → Copy diagnostics and paste the result into your support ticket. It never includes your PIN or serial.'],
