    'faqs' => [
        ['q' => 'Does StageWatch need the internet?', 'a' => 'No. Everything runs on the venue\'s own network, including every phone, tablet and TV screen. The internet is only used for optional extras: the cloud AI copilot, Google Sheets import and the time-server clock check.'],
        ['q' => 'Is there a free trial?', 'a' => 'Yes. You get 14 days with every feature and no watermark, starting the first time you open StageWatch. After that it keeps working as a free basic timer.'],
        ['q' => 'What does the free mode do after the trial?', 'a' => 'StageWatch stays a basic timer for ever: countdown, count-up, time of day, nudge, typed messages, warning colours, blackout, two presets and the full-screen output. Every output carries a small "StageWatch by Ben Rohleder" watermark until you install a licence.'],
        ['q' => 'Which licence do I need?', 'a' => 'Standard (£9) covers the core timer, NDI and keyed outputs. Pro (£29) is for one operator and one room: the running order, browser screens, Companion, PowerPoint and Q&A. Production (£79, launch price £59) adds the crew loop, forecast, multi-room, cue lights, LTC, VT countdowns, the AI copilot and a backup PC.'],
        ['q' => 'Does StageWatch work with Bitfocus Companion?', 'a' => 'Yes. A full Companion module ships with StageWatch, with live timer keys that change colour, keys for every preset and running-order item, and a ready-made 32-key Showcaller page. It needs Pro or Production and Companion 5.0 or newer.'],
        ['q' => 'Can the timer follow my PowerPoint slides?', 'a' => 'Yes, with no add-in. StageWatch reads the slideshow running on the same PC and shows slide n of N, the next slide\'s title and your pace against the rehearsal. If the slides run on a lectern PC, run StageWatch Slides there. Slide awareness is part of Pro.'],
        ['q' => 'How do speakers confirm a cue?', 'a' => 'Tick Ask to acknowledge and the speaker screen shows a Got it button. The speaker taps it, or presses a podium Stream Deck key, and you see the cue change from waiting to acknowledged. A cue nobody answers escalates after 20 seconds. Confirmed cues are part of Production.'],
        ['q' => 'Can I put the countdown into a vision mixer or over NDI?', 'a' => 'Yes. Keyed full screen puts the timer on solid blue, green, magenta or black for a chroma or luma key, and the NDI output sends the same picture to vMix, OBS and NDI-capable mixers. Both come with Standard, and NDI needs the free NDI Runtime.'],
        ['q' => 'Can I run a backup PC?', 'a' => 'Yes. A Production licence covers a main and a backup PC. Open the same show file on both, and presenter PCs running StageWatch Slides send their slides to both machines.'],
        ['q' => 'Does StageWatch run on a Mac?', 'a' => 'The StageWatch desk runs on Windows 10 and 11 (64-bit). Macs, iPhones, iPads, Android devices and smart TVs can all show StageWatch screens and crew pages in a browser, with nothing to install.'],
        ['q' => 'Can AI change my show by itself?', 'a' => 'Not unless you allow it. AI suggestions wait in the Copilot list until a person approves them, and anything that changes the room is never pre-ticked. You can choose to let a connected AI agent act directly, but agents propose by default.'],
        ['q' => 'Does the AI send my show data anywhere?', 'a' => 'Only if you turn on the optional cloud copilot with your own Anthropic API key, or connect an AI agent of your own. The copilot then sends show details such as the running order, timings and messages to Anthropic. The built-in assistant, the forecast and speech pace work offline, and voice stays on the PC.'],
    ],
    'glossary' => [
        ['term' => 'Running order', 'definition' => 'The show\'s agenda of items, stepped through with Next. Also called the rundown or run of show.'],
        ['term' => 'Preset', 'definition' => 'One of 12 one-click timers for the times you use most.'],
        ['term' => 'Nudge', 'definition' => 'Adding or removing time while the timer runs.'],
        ['term' => 'End at', 'definition' => 'Finishing at a clock time, either by stretching the countdown (elastic) or by counting the real time left.'],
        ['term' => 'Cue ladder', 'definition' => 'The graduated signals a speaker sees, such as Keynote 10/5/2/0 or Toastmasters green/yellow/red.'],
        ['term' => 'Cue label', 'definition' => 'Words such as "5 MIN" or "WRAP UP" on the speaker screen, so a cue never relies on colour.'],
        ['term' => 'Finish by', 'definition' => 'The clock time the speaker should finish, which moves when you nudge.'],
        ['term' => 'Calm clock', 'definition' => 'A speaker clock that shows "12 MIN" instead of ticking seconds.'],
        ['term' => 'Honest clock', 'definition' => 'The speaker always sees the real time left, even while you stretch time.'],
        ['term' => 'Briefing preview', 'definition' => 'The whole cue ladder played at 10 times speed, so a speaker sees every signal before the show.'],
        ['term' => 'Quick message', 'definition' => 'A saved message you send in one click.'],
        ['term' => 'Acknowledged cue', 'definition' => 'A cue the speaker or crew confirms with a tap on Got it. The desk marks it waiting (amber), acknowledged (green) or unanswered (red, flashing).'],
        ['term' => 'STANDBY and GO', 'definition' => 'A department\'s cue on its own page, confirmed by that department.'],
        ['term' => 'ALL GO', 'definition' => 'One press that GOes every department standing by, at the same moment.'],
        ['term' => 'Call to stage', 'definition' => 'A green-room call such as "Ana to stage", answered with Found, then In position.'],
        ['term' => 'Pocket buzz', 'definition' => 'A silent cue on a phone: it vibrates on Android and flashes on iPhone.'],
        ['term' => 'Crew link', 'definition' => 'A personal link that lets one crew page confirm its own cues.'],
        ['term' => 'Curfew', 'definition' => 'A hard-out time the show must not overrun.'],
        ['term' => 'Fixed start', 'definition' => 'An item held to a published start time.'],
        ['term' => 'Buffer', 'definition' => 'An item that shrinks to absorb lateness.'],
        ['term' => 'Trim', 'definition' => 'Cutting or extending an item, kept apart from the plan so the report shows both.'],
        ['term' => 'Delay', 'definition' => 'An announced delay that ripples on until a gap absorbs it.'],
        ['term' => 'Catch up', 'definition' => 'Re-timing the live item so it lands on its planned end.'],
        ['term' => 'Recover time', 'definition' => 'Winning back minutes across the coming items, with a preview before you apply it.'],
        ['term' => 'Roll', 'definition' => 'The running order runs itself by its planned times until you take over.'],
        ['term' => 'Forecast', 'definition' => 'The likely end time and curfew risk, learned from your own shows.'],
        ['term' => 'Assistant', 'definition' => 'Built-in, offline suggestions you apply with a click.'],
        ['term' => 'Copilot', 'definition' => 'The optional AI that turns plain English into a plan you approve.'],
        ['term' => 'Holding image', 'definition' => 'A still, such as a walk-in slide or sponsor card, put full screen on every screen.'],
        ['term' => 'Keyed output', 'definition' => 'A full-screen output on a solid colour, for a vision mixer\'s chroma or luma key.'],
        ['term' => 'Floating mini timer', 'definition' => 'A small, always-on-top timer for your own screen.'],
        ['term' => 'NDI', 'definition' => 'A way to send video over the network to vMix, OBS and video mixers.'],
